static const size_t symbols_libcod2x_count = sizeof(symbols_libcod2x) / sizeof(symbols_libcod2x[0]);

// Binary search: returns the LibCod2xSymbol whose range contains 'rva', or nullptr.
static inline const LibCod2xSymbol* symbols_libcod2x_find(uint32_t rva)
{
    int lo = 0;
    int hi = (int)symbols_libcod2x_count - 1;
    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;
        const LibCod2xSymbol& f = symbols_libcod2x[mid];
        if (rva < f.rva) hi = mid - 1;
        else if (f.len > 0 && rva >= f.rva + f.len) lo = mid + 1;
        else return &symbols_libcod2x[mid];
    }
    return nullptr;
}

